// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */
#include <kunit/test.h>
#include <linux/kernel.h>
#include <linux/limits.h>
#include <linux/string.h>

/* ASCII-only case folding, matching the kernel's tolower() */
static int ascii_lower(int c)
{
	return (c >= 'A' && c <= 'Z') ? c + ('a' - 'A') : c;
}

static int sign_of(int v)
{
	return (v > 0) - (v < 0);
}

static void agent_test_equal_strings(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("hello", "hello", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("hello", "hello", 100), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("x", "x", 1), 0);
}

static void agent_test_case_insensitive_equal(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("ABC", "abc", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "ABC", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("HeLLo wOrld", "hello WORLD", 11), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("ab", "AB", 2), 0);
}

static void agent_test_exact_return_values(struct kunit *test)
{
	/* Mismatches are reported as the difference of the folded chars */
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "c", 1), -2);
	KUNIT_EXPECT_EQ(test, strncasecmp("c", "a", 1), 2);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "ABD", 3), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("ABD", "abc", 3), 1);
	KUNIT_EXPECT_EQ(test, strncasecmp("Y", "z", 1), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("Z", "z", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("q", "Q", 1), 0);
}

static void agent_test_ordering_sign(struct kunit *test)
{
	KUNIT_EXPECT_LT(test, strncasecmp("apple", "banana", 5), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("banana", "apple", 5), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("APPLE", "apricot", 7), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("Zebra", "apple", 5), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abcd", 4), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abcd", "ABC", 4), 0);
}

static void agent_test_zero_length(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "xyz", 0), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "a", 0), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "", 0), 0);
}

static void agent_test_length_boundary(struct kunit *test)
{
	/* A mismatch at index len-1 must be seen; index len must not */
	KUNIT_EXPECT_EQ(test, strncasecmp("abcX", "abcY", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abcX", "abcY", 4), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("abcx", "ABCY", 4), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abd", 2), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abd", 3), -1);
}

static void agent_test_length_one(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "A", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("ab", "AC", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("ab", "AC", 2), -1);
}

static void agent_test_prefix_and_nul(struct kunit *test)
{
	/* Shorter string hits NUL first: result must be nonzero */
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abcd", 4), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abcd", "abc", 4), 0);
	/* Embedded NUL terminates the comparison */
	KUNIT_EXPECT_EQ(test, strncasecmp("ab\0cd", "AB\0xy", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "ABC", SIZE_MAX), 0);
}

static void agent_test_empty_strings(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("", "", 10), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("", "a", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("a", "", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("", "A", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("A", "", 1), 0);
}

static void agent_test_unsigned_comparison(struct kunit *test)
{
	/* Bytes >= 0x80 must compare as unsigned char */
	KUNIT_EXPECT_GT(test, strncasecmp("\xff", "\x01", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("\x80", "\x7f", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("\x01", "\xff", 1), 0);
	/* Non-ASCII bytes are not case-folded */
	KUNIT_EXPECT_EQ(test, strncasecmp("\xc0", "\xe0", 1), -32);
}

static void agent_test_non_letters_not_folded(struct kunit *test)
{
	/* Characters adjacent to 'A'-'Z' and 'a'-'z' must not fold */
	KUNIT_EXPECT_GT(test, strncasecmp("Z", "[", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("@", "a", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("`", "a", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("[", "{", 1), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("[", "{", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("@", "@", 1), 0);
}

static void agent_test_max_length(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "ABC", SIZE_MAX), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abd", SIZE_MAX), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "ABCD", SIZE_MAX), 0);
}

static void agent_test_symmetry(struct kunit *test)
{
	static const struct {
		const char *a;
		const char *b;
		size_t len;
	} pairs[] = {
		{ "Hello", "help", 5 },
		{ "HELLO", "hello", 5 },
		{ "abc", "abd", 3 },
		{ "a", "", 1 },
		{ "Q", "[", 1 },
		{ "xyz", "XY", 3 },
	};
	size_t i;

	for (i = 0; i < ARRAY_SIZE(pairs); i++) {
		int fwd = strncasecmp(pairs[i].a, pairs[i].b, pairs[i].len);
		int rev = strncasecmp(pairs[i].b, pairs[i].a, pairs[i].len);

		KUNIT_EXPECT_EQ(test, sign_of(fwd), -sign_of(rev));
	}
}

/* Exhaustive over all single-byte pairs, including NUL */
static void agent_test_exhaustive_single_char(struct kunit *test)
{
	char a[2] = { 0, 0 };
	char b[2] = { 0, 0 };
	int c1, c2, expected, got;

	for (c1 = 0; c1 < 256; c1++) {
		for (c2 = 0; c2 < 256; c2++) {
			a[0] = (char)c1;
			b[0] = (char)c2;

			/* A NUL on either side breaks out before folding */
			if (!c1 || !c2)
				expected = c1 - c2;
			else
				expected = ascii_lower(c1) - ascii_lower(c2);

			got = strncasecmp(a, b, 1);
			if (got != expected) {
				KUNIT_FAIL(test,
					   "strncasecmp(%d, %d, 1) = %d, expected %d",
					   c1, c2, got, expected);
				return;
			}
		}
	}
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_test_equal_strings),
	KUNIT_CASE(agent_test_case_insensitive_equal),
	KUNIT_CASE(agent_test_exact_return_values),
	KUNIT_CASE(agent_test_ordering_sign),
	KUNIT_CASE(agent_test_zero_length),
	KUNIT_CASE(agent_test_length_boundary),
	KUNIT_CASE(agent_test_length_one),
	KUNIT_CASE(agent_test_prefix_and_nul),
	KUNIT_CASE(agent_test_empty_strings),
	KUNIT_CASE(agent_test_unsigned_comparison),
	KUNIT_CASE(agent_test_non_letters_not_folded),
	KUNIT_CASE(agent_test_max_length),
	KUNIT_CASE(agent_test_symmetry),
	KUNIT_CASE(agent_test_exhaustive_single_char),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

MODULE_LICENSE("GPL");

// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */
#include <kunit/test.h>
#include <linux/kernel.h>
#include <linux/string.h>

/* Empty subject: nothing to scan, so the span is zero. */
static void agent_strcspn_empty_subject(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("", "abc"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("", ""), (size_t)0);
}

/* Empty reject set: nothing ever matches, so the whole string is the span. */
static void agent_strcspn_empty_reject(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", ""), (size_t)6);
	KUNIT_EXPECT_EQ(test, strcspn("a", ""), (size_t)1);
}

/* No character of the subject is in the reject set. */
static void agent_strcspn_no_match(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", "xyz"), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("hello", "HELLO"), (size_t)5);
}

/* Match on the very first character gives a span of zero. */
static void agent_strcspn_match_first(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abc", "a"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("abc", "cba"), (size_t)0);
}

/* Match on the last character: span is length - 1, not length. */
static void agent_strcspn_match_last(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abc", "c"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("ab", "b"), (size_t)1);
}

/* Match in the middle stops exactly at that character. */
static void agent_strcspn_match_middle(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello world", " "), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("key=value", "="), (size_t)3);
}

/* With several reject characters, the earliest one in s wins. */
static void agent_strcspn_earliest_of_many(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "fed"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("xyzq", "qz"), (size_t)1);
}

/* Single-character subject: match and no-match boundaries. */
static void agent_strcspn_single_char(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("a", "a"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("a", "b"), (size_t)1);
}

/* Repeated characters in the subject do not affect the first-match index. */
static void agent_strcspn_repeated_chars(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("aaaab", "b"), (size_t)4);
	KUNIT_EXPECT_EQ(test, strcspn("aaaab", "a"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("bbbb", "ab"), (size_t)0);
}

/* Duplicated characters in the reject set behave like a single one. */
static void agent_strcspn_duplicate_reject(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcabc", "cc"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("xxxy", "yyyy"), (size_t)3);
}

/* Comparison must be byte-exact: case matters and high-bit bytes work. */
static void agent_strcspn_case_and_high_bytes(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcABC", "A"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("abc", "C"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("ab\xff" "cd", "\xff"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("ab\x80" "cd", "\x80"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("ab\xff" "cd", "\x7f"), (size_t)5);
}

/*
 * The reject set ends at its first NUL, so bytes after it are not members.
 * Here 'b' sits after the terminator and must not stop the scan.
 */
static void agent_strcspn_reject_terminator(struct kunit *test)
{
	static const char reject[] = "a\0b";

	KUNIT_EXPECT_EQ(test, strcspn("xb", reject), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("xa", reject), (size_t)1);
}

/*
 * The subject ends at its first NUL, so bytes after it must not be scanned.
 * The 'c' after the terminator must not be reported as a match.
 */
static void agent_strcspn_subject_terminator(struct kunit *test)
{
	static const char subject[] = "ab\0c";

	KUNIT_EXPECT_EQ(test, strcspn(subject, "c"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn(subject, ""), (size_t)2);
}

/* Subject made entirely of reject characters: span is zero. */
static void agent_strcspn_all_rejected(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("aaaa", "a"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("abba", "ab"), (size_t)0);
}

/* Long subject: the match position must be exact at a large offset. */
static void agent_strcspn_long_string(struct kunit *test)
{
	char *buf = kunit_kzalloc(test, 4097, GFP_KERNEL);
	size_t i;

	KUNIT_ASSERT_NOT_NULL(test, buf);

	memset(buf, 'x', 4096);
	KUNIT_EXPECT_EQ(test, strcspn(buf, "y"), (size_t)4096);

	buf[4095] = 'y';
	KUNIT_EXPECT_EQ(test, strcspn(buf, "y"), (size_t)4095);

	buf[4095] = 'x';
	buf[0] = 'y';
	KUNIT_EXPECT_EQ(test, strcspn(buf, "y"), (size_t)0);

	/* Each position in turn: the span must equal that index. */
	buf[0] = 'x';
	for (i = 0; i < 4096; i += 511) {
		buf[i] = 'z';
		KUNIT_EXPECT_EQ(test, strcspn(buf, "z"), i);
		buf[i] = 'x';
	}
}

/* Consistency with strpbrk(): the pointer offset equals strcspn(). */
static void agent_strcspn_matches_strpbrk(struct kunit *test)
{
	static const char *subjects[] = { "hello, world", "/usr/bin/env", "abc", "" };
	static const char *rejects[] = { " ,", "/", "xyz", "" };
	size_t i, j;

	for (i = 0; i < ARRAY_SIZE(subjects); i++) {
		for (j = 0; j < ARRAY_SIZE(rejects); j++) {
			const char *hit = strpbrk(subjects[i], rejects[j]);
			size_t span = strcspn(subjects[i], rejects[j]);

			if (hit)
				KUNIT_EXPECT_EQ(test, span, (size_t)(hit - subjects[i]));
			else
				KUNIT_EXPECT_EQ(test, span, strlen(subjects[i]));
		}
	}
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_strcspn_empty_subject),
	KUNIT_CASE(agent_strcspn_empty_reject),
	KUNIT_CASE(agent_strcspn_no_match),
	KUNIT_CASE(agent_strcspn_match_first),
	KUNIT_CASE(agent_strcspn_match_last),
	KUNIT_CASE(agent_strcspn_match_middle),
	KUNIT_CASE(agent_strcspn_earliest_of_many),
	KUNIT_CASE(agent_strcspn_single_char),
	KUNIT_CASE(agent_strcspn_repeated_chars),
	KUNIT_CASE(agent_strcspn_duplicate_reject),
	KUNIT_CASE(agent_strcspn_case_and_high_bytes),
	KUNIT_CASE(agent_strcspn_reject_terminator),
	KUNIT_CASE(agent_strcspn_subject_terminator),
	KUNIT_CASE(agent_strcspn_all_rejected),
	KUNIT_CASE(agent_strcspn_long_string),
	KUNIT_CASE(agent_strcspn_matches_strpbrk),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

MODULE_DESCRIPTION("KUnit tests for strcspn");
MODULE_LICENSE("GPL");

// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Exercises string_get_size() in lib/string_helpers.c: unit selection,
 * the 1000/1024 thresholds, three-significant-figure rounding and its
 * carry, block size handling, the NO_SPACE/NO_BYTES flags, 32/64-bit
 * limits, the "UNK" overflow suffix, and the snprintf() truncation contract.
 */
#include <kunit/test.h>
#include <linux/module.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

/*
 * Call string_get_size() with a sentinel-filled buffer and compare both the
 * produced string and the return value (length the full output would have).
 */
static void check_size(struct kunit *test, u64 size, u64 blk_size,
		       enum string_size_units units, const char *expected)
{
	char buf[32];
	int ret;

	memset(buf, 'x', sizeof(buf));
	ret = string_get_size(size, blk_size, units, buf, sizeof(buf));

	KUNIT_EXPECT_STREQ(test, buf, expected);
	KUNIT_EXPECT_EQ(test, ret, (int)strlen(expected));
}

static void test_zero_size(struct kunit *test)
{
	check_size(test, 0, 1, STRING_UNITS_10, "0 B");
	check_size(test, 0, 1, STRING_UNITS_2, "0 B");
	check_size(test, 0, 4096, STRING_UNITS_2, "0 B");
	/* A zero block size makes the total zero, whatever the count is. */
	check_size(test, 5, 0, STRING_UNITS_10, "0 B");
	check_size(test, 5, 0, STRING_UNITS_2, "0 B");
}

static void test_bytes_below_threshold(struct kunit *test)
{
	/* One byte is rendered with three significant figures. */
	check_size(test, 1, 1, STRING_UNITS_10, "1.00 B");
	check_size(test, 512, 1, STRING_UNITS_10, "512 B");
	check_size(test, 999, 1, STRING_UNITS_10, "999 B");
	/* Base 2 only scales at 1024, so 1000 is still plain bytes. */
	check_size(test, 999, 1, STRING_UNITS_2, "999 B");
	check_size(test, 1000, 1, STRING_UNITS_2, "1000 B");
	check_size(test, 1023, 1, STRING_UNITS_2, "1023 B");
}

static void test_si_boundaries(struct kunit *test)
{
	check_size(test, 1000, 1, STRING_UNITS_10, "1.00 kB");
	check_size(test, 999000, 1, STRING_UNITS_10, "999 kB");
	check_size(test, 1000000, 1, STRING_UNITS_10, "1.00 MB");
	check_size(test, 1048576, 1, STRING_UNITS_10, "1.05 MB");
}

static void test_iec_boundaries(struct kunit *test)
{
	check_size(test, 1024, 1, STRING_UNITS_2, "1.00 KiB");
	check_size(test, 1536, 1, STRING_UNITS_2, "1.50 KiB");
	check_size(test, 1048576, 1, STRING_UNITS_2, "1.00 MiB");
	/* Base 10 does not scale at 1024; it gives the 1.02 kB result. */
	check_size(test, 1024, 1, STRING_UNITS_10, "1.02 kB");
}

static void test_three_significant_figures(struct kunit *test)
{
	/* One integer digit: two decimals. */
	check_size(test, 1023, 1, STRING_UNITS_10, "1.02 kB");
	check_size(test, 1994, 1, STRING_UNITS_10, "1.99 kB");
	check_size(test, 1500, 1, STRING_UNITS_10, "1.50 kB");
	/* Two integer digits: one decimal. */
	check_size(test, 12345, 1, STRING_UNITS_10, "12.3 kB");
	/* Three integer digits: no decimals. */
	check_size(test, 123456, 1, STRING_UNITS_10, "123 kB");
	/* Base 2 converts the remainder to decimal: 476/1024 = 0.46. */
	check_size(test, 1500, 1, STRING_UNITS_2, "1.46 KiB");
}

static void test_round_carry(struct kunit *test)
{
	/* Rounding a 2 decimal place value up to 2.00 with carry into the integer. */
	check_size(test, 1999, 1, STRING_UNITS_10, "2.00 kB");
	/* Rounding a 1 decimal place value up to 13.0 with carry. */
	check_size(test, 12960, 1, STRING_UNITS_10, "13.0 kB");
	/* Rounding 9.95 stays at 9.95 (955 < 1000, no carry). */
	check_size(test, 9950, 1, STRING_UNITS_10, "9.95 kB");
	/* 2047 bytes is 1.999 KiB, which rounds up to 2.00 KiB. */
	check_size(test, 2047, 1, STRING_UNITS_2, "2.00 KiB");
}

static void test_block_size(struct kunit *test)
{
	check_size(test, 2, 512, STRING_UNITS_2, "1.00 KiB");
	check_size(test, 3, 4096, STRING_UNITS_2, "12.0 KiB");
	check_size(test, 1, 1048576, STRING_UNITS_10, "1.05 MB");
	check_size(test, 1, 1ULL << 40, STRING_UNITS_2, "1.00 TiB");
}

static void test_suffix_flags(struct kunit *test)
{
	check_size(test, 1000, 1,
		   STRING_UNITS_10 | STRING_UNITS_NO_SPACE, "1.00kB");
	check_size(test, 1000, 1,
		   STRING_UNITS_10 | STRING_UNITS_NO_BYTES, "1.00 k");
	check_size(test, 1000, 1,
		   STRING_UNITS_10 | STRING_UNITS_NO_SPACE | STRING_UNITS_NO_BYTES,
		   "1.00k");
	check_size(test, 0, 1,
		   STRING_UNITS_10 | STRING_UNITS_NO_SPACE, "0B");
	check_size(test, 1024, 1,
		   STRING_UNITS_2 | STRING_UNITS_NO_BYTES, "1.00 Ki");
}

static void test_32bit_limit(struct kunit *test)
{
	/* 2^32 - 1 is the largest value that takes the non-reduced path. */
	check_size(test, 0xFFFFFFFFULL, 1, STRING_UNITS_2, "4.00 GiB");
	check_size(test, 0xFFFFFFFFULL, 1, STRING_UNITS_10, "4.29 GB");
	/* 2^32 needs the initial reduction loop. */
	check_size(test, 1ULL << 32, 1, STRING_UNITS_2, "4.00 GiB");
}

static void test_large_prefixes(struct kunit *test)
{
	/* 2^40 * 2^40 = 2^80 = 1 YiB, reached through the block size reduction. */
	check_size(test, 1ULL << 40, 1ULL << 40, STRING_UNITS_2, "1.00 YiB");
	/* 2^45 * 2^45 = 2^90 needs a ninth prefix, past the table: "UNK". */
	check_size(test, 1ULL << 45, 1ULL << 45, STRING_UNITS_2, "1.00 UNKB");
}

static void test_output_truncation(struct kunit *test)
{
	char buf[16];
	int ret;

	/* "1.00 KiB" is 8 chars; a 4 byte buffer keeps "1.0" and the NUL. */
	memset(buf, 'x', sizeof(buf));
	ret = string_get_size(1024, 1, STRING_UNITS_2, buf, 4);
	KUNIT_EXPECT_EQ(test, ret, 8);
	KUNIT_EXPECT_STREQ(test, buf, "1.0");

	/* A 1 byte buffer keeps only the NUL terminator. */
	memset(buf, 'x', sizeof(buf));
	ret = string_get_size(1024, 1, STRING_UNITS_2, buf, 1);
	KUNIT_EXPECT_EQ(test, ret, 8);
	KUNIT_EXPECT_STREQ(test, buf, "");

	/* A 0 length buffer is not written to at all. */
	memset(buf, 'x', sizeof(buf));
	ret = string_get_size(1024, 1, STRING_UNITS_2, buf, 0);
	KUNIT_EXPECT_EQ(test, ret, 8);
	KUNIT_EXPECT_EQ(test, buf[0], 'x');
}

