// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Covers string_escape_mem() from lib/string_helpers.c: every escape class,
 * the priority between classes, the @only dictionary and %ESCAPE_APPEND,
 * source length handling, and destination truncation at every size.
 */

#include <kunit/test.h>
#include <linux/array_size.h>
#include <linux/gfp.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

/* Large enough for every expected output used below, with headroom. */
#define AGENT_BUF_SIZE		((size_t)4096)

/*
 * Check string_escape_mem() output for @src against @exp.
 *
 * The length query (NULL destination, size 0) must return @elen. Then for every
 * destination size from 0 to @elen + 1 the return value must still be @elen,
 * the bytes written must be the matching prefix of @exp, and nothing at or
 * past @osz may be touched (checked against a sentinel fill).
 */
static void check_escape(struct kunit *test, const char *src, size_t isz,
			 unsigned int flags, const char *only,
			 const char *exp, size_t elen)
{
	char *buf = kunit_kmalloc(test, AGENT_BUF_SIZE, GFP_KERNEL);
	size_t osz, i;
	int ret;

	KUNIT_ASSERT_NOT_NULL(test, buf);
	KUNIT_ASSERT_LT(test, elen, AGENT_BUF_SIZE);

	ret = string_escape_mem(src, isz, NULL, 0, flags, only);
	KUNIT_ASSERT_EQ_MSG(test, ret, (int)elen, "length query");

	for (osz = 0; osz <= elen + 1; osz++) {
		memset(buf, 'Z', AGENT_BUF_SIZE);
		ret = string_escape_mem(src, isz, buf, osz, flags, only);
		KUNIT_ASSERT_EQ_MSG(test, ret, (int)elen, "osz=%zu", osz);
		KUNIT_ASSERT_MEMEQ_MSG(test, buf, exp, osz < elen ? osz : elen,
				       "osz=%zu", osz);

		for (i = osz; i < AGENT_BUF_SIZE; i++)
			if (buf[i] != 'Z')
				break;
		KUNIT_ASSERT_EQ_MSG(test, i, AGENT_BUF_SIZE,
				    "wrote at or past osz=%zu", osz);
	}
}

#define CHECK_STR(test, src, flags, only, exp)				\
	check_escape((test), (src), strlen(src), (flags), (only),	\
		     (exp), strlen(exp))

static void test_empty_input(struct kunit *test)
{
	char buf[8];

	memset(buf, 'Z', sizeof(buf));
	KUNIT_EXPECT_EQ(test, string_escape_mem("abc", 0, buf, sizeof(buf),
						ESCAPE_ANY_NP, ""), 0);
	KUNIT_EXPECT_MEMEQ(test, buf, "ZZZZZZZZ", sizeof(buf));

	/* Zero-length source is a valid length query with a NULL destination */
	KUNIT_EXPECT_EQ(test, string_escape_mem("abc", 0, NULL, 0,
						ESCAPE_ANY_NP, NULL), 0);
	/* Zero-size destination writes nothing */
	KUNIT_EXPECT_EQ(test, string_escape_mem("abc", 3, buf, 0,
						ESCAPE_ANY_NP, NULL), 3);
	KUNIT_EXPECT_EQ(test, buf[0], 'Z');
}

static void test_source_length_limit(struct kunit *test)
{
	static const char nul_in[] = "a\0b";

	/* Only the first @isz bytes are consumed */
	check_escape(test, "abcdef", 3, 0, NULL, "abc", 3);
	/* Embedded NUL is copied as-is when NULL is not requested */
	check_escape(test, nul_in, 3, 0, NULL, nul_in, 3);
}

static void test_no_flags_passthrough(struct kunit *test)
{
	char in[256];
	int i;

	for (i = 0; i < 256; i++)
		in[i] = i;

	/* No escape class selected: every byte, including 0x00 and 0xff, passes */
	check_escape(test, in, sizeof(in), 0, NULL, in, sizeof(in));
}

static void test_space_escapes(struct kunit *test)
{
	/* Only the five whitespace control characters are escaped */
	CHECK_STR(test, "\n\r\t\v\f ", ESCAPE_SPACE, NULL, "\\n\\r\\t\\v\\f ");
	/* Other control characters and backspace pass through */
	CHECK_STR(test, "a\x01\x7f\b", ESCAPE_SPACE, NULL, "a\x01\x7f\b");
}

static void test_special_escapes(struct kunit *test)
{
	/* Backslash, double quote, BEL and ESC */
	CHECK_STR(test, "\\\"\a\e", ESCAPE_SPECIAL, NULL, "\\\\\\\"\\a\\e");
	/* Single quote, question mark and newline are not special */
	CHECK_STR(test, "'?\n", ESCAPE_SPECIAL, NULL, "'?\n");
}

static void test_null_escape(struct kunit *test)
{
	static const char in[] = { 'a', 0, 'b' };

	check_escape(test, in, sizeof(in), ESCAPE_NULL, NULL, "a\\0b", 4);
	CHECK_STR(test, "0", ESCAPE_NULL, NULL, "0");
	/* NUL is left raw when only other classes are requested */
	check_escape(test, in, sizeof(in), ESCAPE_SPACE | ESCAPE_SPECIAL,
		     NULL, in, sizeof(in));
}

static void test_octal_escape(struct kunit *test)
{
	static const char in[] = {
		0x00, 0x01, 0x08, 0x1b, 0x7f, (char)0x80, (char)0xff,
	};
	static const char exp[] = "\\000\\001\\010\\033\\177\\200\\377";

	check_escape(test, in, sizeof(in), ESCAPE_OCTAL, NULL,
		     exp, sizeof(exp) - 1);
}

static void test_hex_escape(struct kunit *test)
{
	static const char in[] = {
		0x00, 0x0a, 0x5c, (char)0xab, (char)0xff,
	};
	static const char exp[] = "\\x00\\x0a\\x5c\\xab\\xff";

	/* Lowercase hex digits, two per byte */
	check_escape(test, in, sizeof(in), ESCAPE_HEX, NULL,
		     exp, sizeof(exp) - 1);
}

static void test_escape_priority(struct kunit *test)
{
	static const char nul[] = { 0 };

	/* SPACE wins over OCTAL for newline */
	CHECK_STR(test, "\n", ESCAPE_SPACE | ESCAPE_OCTAL, NULL, "\\n");
	/* SPECIAL wins over OCTAL for BEL and double quote */
	CHECK_STR(test, "\a", ESCAPE_SPECIAL | ESCAPE_OCTAL, NULL, "\\a");
	CHECK_STR(test, "\"", ESCAPE_SPECIAL | ESCAPE_OCTAL, NULL, "\\\"");
	/* NULL wins over OCTAL for NUL */
	check_escape(test, nul, 1, ESCAPE_NULL | ESCAPE_OCTAL, NULL, "\\0", 2);
	/* HEX is ignored when OCTAL is also set */
	CHECK_STR(test, "\x01", ESCAPE_HEX | ESCAPE_OCTAL, NULL, "\\001");
}

static void test_escape_any_mixed(struct kunit *test)
{
	static const char in[] = {
		'a', '\n', '"', '\\', 0x01, 0x7f, ' ', 0x00, (char)0xff, 'z',
	};
	static const char exp[] = "a\\n\\\"\\\\\\001\\177 \\0\\377z";
	/*
	 * With NP, printable '"', '\\' and 0xff (printable per the kernel
	 * ctype table) pass through; only non-printables are escaped.
	 */
	static const char exp_np[] = "a\\n\"\\\\001\\177 \\0\xffz";

	check_escape(test, in, sizeof(in), ESCAPE_ANY, NULL,
		     exp, sizeof(exp) - 1);
	check_escape(test, in, sizeof(in), ESCAPE_ANY_NP, NULL,
		     exp_np, strlen(exp_np));
}

static void test_np_passthrough_and_octal(struct kunit *test)
{
	static const char ctrl[] = { 0x0a };
	static const char in2[] = { (char)0x80, (char)0xa0 };
	static const char exp2[] = { '\\', '2', '0', '0', (char)0xa0 };
	char printable[95];
	int i;

	for (i = 0; i < sizeof(printable); i++)
		printable[i] = 0x20 + i;

	/* Printable ASCII, 0x20 through 0x7e, is never escaped */
	check_escape(test, printable, sizeof(printable),
		     ESCAPE_NP | ESCAPE_OCTAL, NULL,
		     printable, sizeof(printable));
	/* Newline is not printable */
	check_escape(test, ctrl, sizeof(ctrl), ESCAPE_NP | ESCAPE_OCTAL, NULL,
		     "\\012", 4);
	/* 0x80 is not printable, 0xa0 (NBSP) is printable in ctype */
	check_escape(test, in2, sizeof(in2), ESCAPE_NP | ESCAPE_OCTAL, NULL,
		     exp2, sizeof(exp2));
}

static void test_nap_vs_na(struct kunit *test)
{
	static const char in[] = {
		'A', 0x01, 0x7f, (char)0x80, (char)0xc3,
	};
	/* NAP: only printable ASCII passes */
	static const char exp_nap[] = "A\\x01\\x7f\\x80\\xc3";
	/* NA: only ASCII passes, so 0x01 and 0x7f stay raw */
	static const char exp_na[] = {
		'A', 0x01, 0x7f, '\\', 'x', '8', '0', '\\', 'x', 'c', '3',
	};
	/* NP: printable passes, so 0xc3 stays raw; 0x01, 0x7f, 0x80 escape */
	static const char exp_np[] = {
		'A', '\\', 'x', '0', '1', '\\', 'x', '7', 'f',
		'\\', 'x', '8', '0', (char)0xc3,
	};

	check_escape(test, in, sizeof(in), ESCAPE_NAP | ESCAPE_HEX, NULL,
		     exp_nap, strlen(exp_nap));
	check_escape(test, in, sizeof(in), ESCAPE_NA | ESCAPE_HEX, NULL,
		     exp_na, sizeof(exp_na));
	check_escape(test, in, sizeof(in), ESCAPE_NP | ESCAPE_HEX, NULL,
		     exp_np, sizeof(exp_np));
}

static void test_only_dictionary(struct kunit *test)
{
	static const char in[] = { 0x01, 'b', 0x02 };
	static const char exp[] = { 0x01, '\\', '1', '4', '2', 0x02 };

	/* Only 'b' is in the dictionary, so the other bytes pass through */
	CHECK_STR(test, "abc", ESCAPE_OCTAL, "b", "a\\142c");
	CHECK_STR(test, "x\"y", ESCAPE_SPECIAL, "\"", "x\\\"y");
	/* Control bytes outside the dictionary are not escaped */
	check_escape(test, in, sizeof(in), ESCAPE_OCTAL, "b",
		     exp, sizeof(exp));
}

static void test_only_empty_equals_null(struct kunit *test)
{
	char *in = kunit_kzalloc(test, 256, GFP_KERNEL);
	char *a = kunit_kzalloc(test, AGENT_BUF_SIZE, GFP_KERNEL);
	char *b = kunit_kzalloc(test, AGENT_BUF_SIZE, GFP_KERNEL);
	int ra, rb, i;

	KUNIT_ASSERT_NOT_NULL(test, in);
	KUNIT_ASSERT_NOT_NULL(test, a);
	KUNIT_ASSERT_NOT_NULL(test, b);

	for (i = 0; i < 256; i++)
		in[i] = i;

	ra = string_escape_mem(in, 256, a, AGENT_BUF_SIZE,
			       ESCAPE_ANY_NP | ESCAPE_HEX, NULL);
	rb = string_escape_mem(in, 256, b, AGENT_BUF_SIZE,
			       ESCAPE_ANY_NP | ESCAPE_HEX, "");
	KUNIT_ASSERT_LT(test, (size_t)ra, AGENT_BUF_SIZE);
	KUNIT_EXPECT_EQ(test, ra, rb);
	KUNIT_EXPECT_MEMEQ(test, a, b, (size_t)ra);
}

static void test_append_flag(struct kunit *test)
{
	/* With APPEND, dictionary bytes are escaped by the remaining classes */
	check_escape(test, "a%b", 3, ESCAPE_APPEND | ESCAPE_NP | ESCAPE_HEX,
		     "%", "a\\x25b", 6);
	/* Without APPEND, NP passes '%' through even though it is in @only */
	check_escape(test, "a%b", 3, ESCAPE_NP | ESCAPE_HEX, "%", "a%b", 3);
	/* APPEND on its own escapes nothing */
	CHECK_STR(test, "a\x01", ESCAPE_APPEND, NULL, "a\x01");
}

static void test_unknown_flags_ignored(struct kunit *test)
{
	/* Bits outside ESCAPE_ALL_MASK select no class: everything passes */
	CHECK_STR(test, "a\n\x01\"\\", 1U << 20, NULL, "a\n\x01\"\\");
}

static void test_exact_fit_no_terminator(struct kunit *test)
{
	char buf[8];

	memset(buf, 'Z', sizeof(buf));
	KUNIT_EXPECT_EQ(test, string_escape_mem("ab\n", 3, buf, 4,
						ESCAPE_SPACE, NULL), 4);
	KUNIT_EXPECT_MEMEQ(test, buf, "ab\\n", 4);
	/* Output exactly fills dst: no NUL is written past it */
	KUNIT_EXPECT_EQ(test, buf[4], 'Z');
}

static void test_truncation_mid_escape(struct kunit *test)
{
	static const char in[] = { 0x01 };
	static const char exp[] = "\\001";
	char buf[8];
	size_t osz;

	/* Each partial prefix of "\001" is written, and the length stays 4 */
	for (osz = 1; osz <= 4; osz++) {
		memset(buf, 'Z', sizeof(buf));
		KUNIT_ASSERT_EQ_MSG(test, string_escape_mem(in, 1, buf, osz,
							    ESCAPE_OCTAL, NULL),
				    4, "osz=%zu", osz);
		KUNIT_EXPECT_MEMEQ_MSG(test, buf, exp, osz, "osz=%zu", osz);
		KUNIT_EXPECT_EQ_MSG(test, buf[osz], 'Z', "osz=%zu", osz);
	}
}

static void test_large_input_truncated(struct kunit *test)
{
	const size_t isz = 4096;
	const size_t osz = 1024;
	char *in = kunit_kmalloc(test, isz, GFP_KERNEL);
	char *out = kunit_kmalloc(test, 2 * osz, GFP_KERNEL);
	char *exp = kunit_kzalloc(test, osz, GFP_KERNEL);
	size_t i;
	int ret;

	KUNIT_ASSERT_NOT_NULL(test, in);
	KUNIT_ASSERT_NOT_NULL(test, out);
	KUNIT_ASSERT_NOT_NULL(test, exp);

	memset(in, 0x01, isz);
	memset(out, 'Z', 2 * osz);

	ret = string_escape_mem(in, isz, out, osz, ESCAPE_OCTAL, NULL);
	/* Full length is reported even though only osz bytes were written */
	KUNIT_EXPECT_EQ(test, ret, (int)(isz * 4));

	for (i = 0; i < osz; i += 4)
		memcpy(exp + i, "\\001", 4);
	KUNIT_EXPECT_MEMEQ(test, out, exp, osz);

	for (i = osz; i < 2 * osz; i++)
		if (out[i] != 'Z')
			break;
	KUNIT_EXPECT_EQ_MSG(test, i, 2 * osz, "wrote past osz");
}

static void test_truncation_property_all_flags(struct kunit *test)
{
	static const unsigned int flag_sets[] = {
		0,
		ESCAPE_ANY,
		ESCAPE_ANY_NP,
		ESCAPE_HEX,
		ESCAPE_OCTAL | ESCAPE_NP,
		ESCAPE_NAP | ESCAPE_HEX,
		ESCAPE_NA | ESCAPE_OCTAL,
		ESCAPE_ANY_NP | ESCAPE_APPEND | ESCAPE_HEX,
		ESCAPE_HEX | ESCAPE_SPACE,
	};
	static const char *onlys[] = { NULL, "%\n\"" };
	char *in = kunit_kmalloc(test, 256, GFP_KERNEL);
	char *full = kunit_kmalloc(test, AGENT_BUF_SIZE, GFP_KERNEL);
	size_t f, o;
	int i, ret;

	KUNIT_ASSERT_NOT_NULL(test, in);
	KUNIT_ASSERT_NOT_NULL(test, full);

	for (i = 0; i < 256; i++)
		in[i] = i;

	/*
	 * Treat the untruncated output as the reference and check that every
	 * destination size reproduces its prefix and reports the same length.
	 */
	for (f = 0; f < ARRAY_SIZE(flag_sets); f++) {
		for (o = 0; o < ARRAY_SIZE(onlys); o++) {
			memset(full, 'Z', AGENT_BUF_SIZE);
			ret = string_escape_mem(in, 256, full, AGENT_BUF_SIZE,
						flag_sets[f], onlys[o]);
			KUNIT_ASSERT_LT(test, (size_t)ret, AGENT_BUF_SIZE);
			check_escape(test, in, 256, flag_sets[f], onlys[o],
				     full, ret);
		}
	}
}

