// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Tests for string_unescape() in lib/string_helpers.c.
 */

#include <kunit/test.h>
#include <linux/module.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

#define AGENT_BUF_LEN	64
#define AGENT_CANARY	0xAA

/*
 * Run string_unescape() on a copy of @src into a canary-filled buffer and
 * check the result against @exp, the fully unescaped output. When @size
 * is smaller than the output, only the first size - 1 bytes are expected,
 * and nothing at or beyond @size may be written.
 */
static void agent_expect_unescape(struct kunit *test, const char *src,
				  unsigned int flags, size_t size,
				  const char *exp)
{
	char in[AGENT_BUF_LEN];
	unsigned char out[AGENT_BUF_LEN];
	size_t full = strlen(exp);
	size_t want = full;
	size_t i;
	int ret;

	strscpy(in, src, sizeof(in));
	memset(out, AGENT_CANARY, sizeof(out));

	if (size && want > size - 1)
		want = size - 1;

	ret = string_unescape(in, (char *)out, size, flags);

	KUNIT_EXPECT_EQ(test, ret, (int)want);
	KUNIT_EXPECT_MEMEQ(test, out, exp, want);
	KUNIT_EXPECT_EQ(test, out[want], 0);

	if (size && size < sizeof(out))
		for (i = size; i < sizeof(out); i++)
			KUNIT_EXPECT_EQ(test, out[i], (unsigned char)AGENT_CANARY);
}

static void agent_unescape_space(struct kunit *test)
{
	unsigned int flags = UNESCAPE_SPACE;

	agent_expect_unescape(test, "\\n", flags, 64, "\n");
	agent_expect_unescape(test, "\\r", flags, 64, "\r");
	agent_expect_unescape(test, "\\t", flags, 64, "\t");
	agent_expect_unescape(test, "\\v", flags, 64, "\v");
	agent_expect_unescape(test, "\\f", flags, 64, "\f");
	agent_expect_unescape(test, "x\\ny\\tz", flags, 64, "x\ny\tz");
}

static void agent_unescape_special(struct kunit *test)
{
	unsigned int flags = UNESCAPE_SPECIAL;

	agent_expect_unescape(test, "\\\"", flags, 64, "\"");
	agent_expect_unescape(test, "\\\\", flags, 64, "\\");
	agent_expect_unescape(test, "\\a", flags, 64, "\a");
	agent_expect_unescape(test, "\\e", flags, 64, "\x1b");
	agent_expect_unescape(test, "\\\"\\\\", flags, 64, "\"\\");
}

static void agent_unescape_hex(struct kunit *test)
{
	unsigned int flags = UNESCAPE_HEX;

	/* Up to two hex digits are consumed; upper and lower case accepted. */
	agent_expect_unescape(test, "\\x41", flags, 64, "A");
	agent_expect_unescape(test, "\\x4", flags, 64, "\x04");
	agent_expect_unescape(test, "\\x414", flags, 64, "A4");
	agent_expect_unescape(test, "\\xAb", flags, 64, "\xab");
	agent_expect_unescape(test, "\\xfF", flags, 64, "\xff");
	agent_expect_unescape(test, "\\x7g", flags, 64, "\x07g");

	/* No valid hex digit after 'x': the backslash is kept literally. */
	agent_expect_unescape(test, "\\xg", flags, 64, "\\xg");
	agent_expect_unescape(test, "\\x", flags, 64, "\\x");
	agent_expect_unescape(test, "\\xx", flags, 64, "\\xx");
	agent_expect_unescape(test, "\\xz1", flags, 64, "\\xz1");
}

static void agent_unescape_octal(struct kunit *test)
{
	unsigned int flags = UNESCAPE_OCTAL;

	agent_expect_unescape(test, "\\1", flags, 64, "\x01");
	agent_expect_unescape(test, "\\12", flags, 64, "\n");
	agent_expect_unescape(test, "\\101", flags, 64, "A");
	agent_expect_unescape(test, "\\40", flags, 64, " ");
	agent_expect_unescape(test, "\\177", flags, 64, "\x7f");
	agent_expect_unescape(test, "\\377", flags, 64, "\xff");

	/* At most three digits are consumed. */
	agent_expect_unescape(test, "\\0377", flags, 64, "\x1f" "7");
	agent_expect_unescape(test, "\\20x", flags, 64, "\x10x");

	/*
	 * The third digit is only taken while the value is below 32, so the
	 * value never exceeds 255.
	 */
	agent_expect_unescape(test, "\\777", flags, 64, "?7");
	agent_expect_unescape(test, "\\400", flags, 64, " 0");

	/* 8 and 9 are not octal digits. */
	agent_expect_unescape(test, "\\8", flags, 64, "\\8");
	agent_expect_unescape(test, "\\9", flags, 64, "\\9");
}

static void agent_unescape_passthrough(struct kunit *test)
{
	unsigned int flags = UNESCAPE_ANY;

	/* Unknown escapes keep the backslash and the following character. */
	agent_expect_unescape(test, "\\q", flags, 64, "\\q");
	agent_expect_unescape(test, "\\y\\q", flags, 64, "\\y\\q");
	agent_expect_unescape(test, "\\ ", flags, 64, "\\ ");

	/* A trailing backslash has nothing to escape and is kept. */
	agent_expect_unescape(test, "\\", flags, 64, "\\");
	agent_expect_unescape(test, "abc\\", flags, 64, "abc\\");

	/* Plain text is copied unchanged. */
	agent_expect_unescape(test, "abc", flags, 64, "abc");
	agent_expect_unescape(test, "no escapes here", flags, 64,
			      "no escapes here");
}

static void agent_unescape_mixed(struct kunit *test)
{
	unsigned int flags = UNESCAPE_ANY;

	agent_expect_unescape(test, "a\\tb\\x41\\101\\\\c", flags, 64,
			      "a\tbAA\\c");
	agent_expect_unescape(test, "\\n\\x41\\101\\\"\\\\", flags, 64,
			      "\nAA\"\\");
	/* An escaped backslash is not reinterpreted. */
	agent_expect_unescape(test, "\\\\n", flags, 64, "\\n");
	agent_expect_unescape(test, "\\\\\\n", flags, 64, "\\\n");
	agent_expect_unescape(test, "\\\\101", flags, 64, "\\101");
	/* An invalid hex escape falls back to a literal "\x". */
	agent_expect_unescape(test, "\\n\\x\\101", flags, 64, "\n\\xA");
}

static void agent_unescape_flag_isolation(struct kunit *test)
{
	/* With no flags nothing is unescaped. */
	agent_expect_unescape(test, "\\n\\x41\\101\\\\", 0, 64,
			      "\\n\\x41\\101\\\\");

	/* Each flag only enables its own escape class. */
	agent_expect_unescape(test, "\\t\\a\\\"", UNESCAPE_SPACE, 64,
			      "\t\\a\\\"");
	agent_expect_unescape(test, "\\a\\t\\\"\\n", UNESCAPE_SPECIAL, 64,
			      "\a\\t\"\\n");
	agent_expect_unescape(test, "\\x41\\101\\n", UNESCAPE_OCTAL, 64,
			      "\\x41A\\n");
	agent_expect_unescape(test, "\\101\\x41\\n", UNESCAPE_HEX, 64,
			      "\\101A\\n");
	agent_expect_unescape(test, "\\n\\101\\\"", UNESCAPE_SPECIAL |
			      UNESCAPE_OCTAL, 64, "\\nA\"");
}

static void agent_unescape_embedded_nul(struct kunit *test)
{
	char in[AGENT_BUF_LEN] = "a\\0b";
	char out[AGENT_BUF_LEN];
	int ret;

	/* "\0" produces a real NUL byte; it is counted in the return value. */
	memset(out, AGENT_CANARY, sizeof(out));
	ret = string_unescape(in, out, sizeof(out), UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 3);
	KUNIT_EXPECT_EQ(test, out[0], 'a');
	KUNIT_EXPECT_EQ(test, out[1], 0);
	KUNIT_EXPECT_EQ(test, out[2], 'b');
	KUNIT_EXPECT_EQ(test, out[3], 0);

	strscpy(in, "\\0", sizeof(in));
	memset(out, AGENT_CANARY, sizeof(out));
	ret = string_unescape(in, out, sizeof(out), UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 1);
	KUNIT_EXPECT_EQ(test, out[0], 0);
	KUNIT_EXPECT_EQ(test, out[1], 0);
}

static void agent_unescape_empty(struct kunit *test)
{
	char in[] = "";
	unsigned char out[4];
	int ret;

	memset(out, AGENT_CANARY, sizeof(out));
	ret = string_unescape(in, (char *)out, sizeof(out), UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 0);
	KUNIT_EXPECT_EQ(test, out[0], 0);
	KUNIT_EXPECT_EQ(test, out[1], (unsigned char)AGENT_CANARY);

	/* A one-byte destination only has room for the terminator. */
	memset(out, AGENT_CANARY, sizeof(out));
	ret = string_unescape(in, (char *)out, 1, UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 0);
	KUNIT_EXPECT_EQ(test, out[0], 0);
	KUNIT_EXPECT_EQ(test, out[1], (unsigned char)AGENT_CANARY);
}

static void agent_unescape_size_zero(struct kunit *test)
{
	/* A size of 0 means the destination is unbounded. */
	agent_expect_unescape(test, "\\n\\t", UNESCAPE_ANY, 0, "\n\t");
	agent_expect_unescape(test, "abc", UNESCAPE_ANY, 0, "abc");
	agent_expect_unescape(test, "\\x41\\101", UNESCAPE_ANY, 0, "AA");
}

static void agent_unescape_size_one(struct kunit *test)
{
	/* Size 1 only has room for the terminating NUL. */
	agent_expect_unescape(test, "abc", UNESCAPE_ANY, 1, "abc");
	agent_expect_unescape(test, "\\n", UNESCAPE_ANY, 1, "\n");
	agent_expect_unescape(test, "\\x41", UNESCAPE_ANY, 1, "A");
}

static void agent_unescape_truncation(struct kunit *test)
{
	/* Output is cut at size - 1 characters, with an exact fit allowed. */
	agent_expect_unescape(test, "abcdef", UNESCAPE_ANY, 2, "abcdef");
	agent_expect_unescape(test, "abcdef", UNESCAPE_ANY, 3, "abcdef");
	agent_expect_unescape(test, "abc", UNESCAPE_ANY, 3, "abc");
	agent_expect_unescape(test, "abc", UNESCAPE_ANY, 4, "abc");
	agent_expect_unescape(test, "abc", UNESCAPE_ANY, 5, "abc");
	agent_expect_unescape(test, "abcdefgh", UNESCAPE_ANY, 6, "abcdefgh");
}

static void agent_unescape_escape_boundary(struct kunit *test)
{
	/* An escape that exactly fills the remaining space must be decoded. */
	agent_expect_unescape(test, "\\n", UNESCAPE_ANY, 2, "\n");
	agent_expect_unescape(test, "\\n", UNESCAPE_ANY, 3, "\n");
	agent_expect_unescape(test, "\\101", UNESCAPE_ANY, 2, "A");
	agent_expect_unescape(test, "\\x41", UNESCAPE_ANY, 2, "A");
	agent_expect_unescape(test, "a\\nb", UNESCAPE_ANY, 3, "a\nb");
	agent_expect_unescape(test, "a\\nb", UNESCAPE_ANY, 4, "a\nb");
	agent_expect_unescape(test, "a\\nb", UNESCAPE_ANY, 5, "a\nb");
	agent_expect_unescape(test, "\\t\\t", UNESCAPE_ANY, 3, "\t\t");
	agent_expect_unescape(test, "\\\\", UNESCAPE_ANY, 2, "\\");
}

static void agent_unescape_no_overflow(struct kunit *test)
{
	/* Long inputs must never write past size - 1 or lose the NUL. */
	agent_expect_unescape(test, "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx",
			      UNESCAPE_ANY, 8, "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx");
	agent_expect_unescape(test, "\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n",
			      UNESCAPE_ANY, 8, "\n\n\n\n\n\n\n\n\n\n");
	agent_expect_unescape(test, "\\x41\\x41\\x41\\x41\\x41", UNESCAPE_ANY, 4,
			      "AAAAA");
}

static void agent_unescape_inplace(struct kunit *test)
{
	char buf[AGENT_BUF_LEN];
	int ret;

	/* Output never outruns input, so unescaping in place is valid. */
	strscpy(buf, "a\\tb\\x41\\101\\\\c", sizeof(buf));
	ret = string_unescape(buf, buf, sizeof(buf), UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_MEMEQ(test, buf, "a\tbAA\\c", 7);
	KUNIT_EXPECT_EQ(test, buf[7], 0);

	strscpy(buf, "\\n\\n\\n", sizeof(buf));
	ret = string_unescape_inplace(buf, UNESCAPE_SPACE);
	KUNIT_EXPECT_EQ(test, ret, 3);
	KUNIT_EXPECT_MEMEQ(test, buf, "\n\n\n", 3);
	KUNIT_EXPECT_EQ(test, buf[3], 0);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_unescape_space),
	KUNIT_CASE(agent_unescape_special),
	KUNIT_CASE(agent_unescape_hex),
	KUNIT_CASE(agent_unescape_octal),
	KUNIT_CASE(agent_unescape_passthrough),
	KUNIT_CASE(agent_unescape_mixed),
	KUNIT_CASE(agent_unescape_flag_isolation),
	KUNIT_CASE(agent_unescape_embedded_nul),
	KUNIT_CASE(agent_unescape_empty),
	KUNIT_CASE(agent_unescape_size_zero),
	KUNIT_CASE(agent_unescape_size_one),
	KUNIT_CASE(agent_unescape_truncation),
	KUNIT_CASE(agent_unescape_escape_boundary),
	KUNIT_CASE(agent_unescape_no_overflow),
	KUNIT_CASE(agent_unescape_inplace),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};

kunit_test_suites(&agent_test_suite);

