#include <kunit/test.h>
#include <linux/kernel.h>
#include <linux/limits.h>
#include <linux/string.h>

/* Value used to detect that get_option() did not write to *pint. */
#define SENTINEL	0x5a5a5a5a

/*
 * Run get_option() on a writable copy of @input and check the return
 * value, the parsed integer and the remaining string (@want_rest).
 */
static void check_option(struct kunit *test, const char *input,
			 int want_ret, int want_val, const char *want_rest)
{
	char buf[64];
	char *str = buf;
	int val = SENTINEL;
	int ret;

	strscpy(buf, input, sizeof(buf));
	ret = get_option(&str, &val);

	KUNIT_EXPECT_EQ_MSG(test, ret, want_ret, "input \"%s\"", input);
	KUNIT_EXPECT_EQ_MSG(test, val, want_val, "input \"%s\"", input);
	KUNIT_EXPECT_STREQ_MSG(test, str, want_rest, "input \"%s\"", input);
}

/* Same as check_option(), but with a NULL @pint (validator mode). */
static void check_option_novalue(struct kunit *test, const char *input,
				 int want_ret, const char *want_rest)
{
	char buf[64];
	char *str = buf;
	int ret;

	strscpy(buf, input, sizeof(buf));
	ret = get_option(&str, NULL);

	KUNIT_EXPECT_EQ_MSG(test, ret, want_ret, "input \"%s\"", input);
	KUNIT_EXPECT_STREQ_MSG(test, str, want_rest, "input \"%s\"", input);
}

static void get_option_null_string_pointer(struct kunit *test)
{
	char *str = NULL;
	int val = SENTINEL;

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 0);
	KUNIT_EXPECT_NULL(test, str);
	KUNIT_EXPECT_EQ(test, val, SENTINEL);
}

static void get_option_empty_string(struct kunit *test)
{
	char buf[] = "";
	char *str = buf;
	int val = SENTINEL;

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 0);
	KUNIT_EXPECT_PTR_EQ(test, str, buf);
	KUNIT_EXPECT_EQ(test, val, SENTINEL);
}

static void get_option_single_digit(struct kunit *test)
{
	check_option(test, "7", 1, 7, "");
}

static void get_option_zero(struct kunit *test)
{
	check_option(test, "0", 1, 0, "");
}

static void get_option_multi_digit(struct kunit *test)
{
	check_option(test, "12345", 1, 12345, "");
}

static void get_option_leading_zeros_octal(struct kunit *test)
{
	/* Base 0: a leading zero selects octal. */
	check_option(test, "010", 1, 8, "");
	check_option(test, "007", 1, 7, "");
}

static void get_option_hex_prefix(struct kunit *test)
{
	check_option(test, "0x1f", 1, 31, "");
	check_option(test, "0X10", 1, 16, "");
}

static void get_option_invalid_octal_digit(struct kunit *test)
{
	/* '8' is not an octal digit, so parsing stops before it. */
	check_option(test, "08", 1, 0, "8");
}

static void get_option_int_max(struct kunit *test)
{
	check_option(test, "2147483647", 1, INT_MAX, "");
}

static void get_option_int_min(struct kunit *test)
{
	check_option(test, "-2147483648", 1, INT_MIN, "");
}

static void get_option_negative(struct kunit *test)
{
	check_option(test, "-1", 1, -1, "");
	check_option(test, "-42", 1, -42, "");
}

static void get_option_negative_zero(struct kunit *test)
{
	check_option(test, "-0", 1, 0, "");
}

static void get_option_comma_terminated(struct kunit *test)
{
	/* A comma is consumed and reported as return value 2. */
	check_option(test, "5,rest", 2, 5, "rest");
	check_option(test, "0,9", 2, 0, "9");
	check_option(test, "5,", 2, 5, "");
}

static void get_option_negative_comma_terminated(struct kunit *test)
{
	check_option(test, "-5,9", 2, -5, "9");
}

static void get_option_range(struct kunit *test)
{
	/* Hyphen is not consumed; the caller handles the range. */
	check_option(test, "3-7", 3, 3, "-7");
	check_option(test, "0-0", 3, 0, "-0");
}

static void get_option_negative_range(struct kunit *test)
{
	check_option(test, "-3-7", 3, -3, "-7");
}

static void get_option_hyphen_without_digits(struct kunit *test)
{
	/* The leading hyphen is consumed even though no integer follows. */
	check_option(test, "-", 0, 0, "");
	check_option(test, "-abc", 0, 0, "abc");
	check_option(test, "-,", 0, 0, ",");
}

static void get_option_double_hyphen(struct kunit *test)
{
	/* Only one leading hyphen is consumed; "-5" is not a number. */
	check_option(test, "--5", 0, 0, "-5");
}

static void get_option_no_digits(struct kunit *test)
{
	check_option(test, "abc", 0, 0, "abc");
	check_option(test, ",", 0, 0, ",");
	check_option(test, "+5", 0, 0, "+5");
}

static void get_option_digits_then_garbage(struct kunit *test)
{
	check_option(test, "12abc", 1, 12, "abc");
	check_option(test, "5 6", 1, 5, " 6");
	check_option(test, "5-", 3, 5, "-");
}

static void get_option_null_pint(struct kunit *test)
{
	/* With @pint == NULL the parsed value is discarded, return codes hold. */
	check_option_novalue(test, "42", 1, "");
	check_option_novalue(test, "42,x", 2, "x");
	check_option_novalue(test, "7-9", 3, "-9");
	check_option_novalue(test, "x", 0, "x");
}

static void get_option_sequence(struct kunit *test)
{
	/* Walk "1,2-4,-5" the way get_options() does. */
	char buf[] = "1,2-4,-5";
	char *str = buf;
	int val = SENTINEL;

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 2);
	KUNIT_EXPECT_EQ(test, val, 1);
	KUNIT_EXPECT_STREQ(test, str, "2-4,-5");

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 3);
	KUNIT_EXPECT_EQ(test, val, 2);
	KUNIT_EXPECT_STREQ(test, str, "-4,-5");

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 2);
	KUNIT_EXPECT_EQ(test, val, -4);
	KUNIT_EXPECT_STREQ(test, str, "-5");

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 1);
	KUNIT_EXPECT_EQ(test, val, -5);
	KUNIT_EXPECT_STREQ(test, str, "");

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 0);
	KUNIT_EXPECT_STREQ(test, str, "");
}

static void get_option_does_not_modify_input(struct kunit *test)
{
	char buf[] = "123,456";
	char *str = buf;
	int val = 0;

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 2);
	KUNIT_EXPECT_STREQ(test, buf, "123,456");
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(get_option_null_string_pointer),
	KUNIT_CASE(get_option_empty_string),
	KUNIT_CASE(get_option_single_digit),
	KUNIT_CASE(get_option_zero),
	KUNIT_CASE(get_option_multi_digit),
	KUNIT_CASE(get_option_leading_zeros_octal),
	KUNIT_CASE(get_option_hex_prefix),
	KUNIT_CASE(get_option_invalid_octal_digit),
	KUNIT_CASE(get_option_int_max),
	KUNIT_CASE(get_option_int_min),
	KUNIT_CASE(get_option_negative),
	KUNIT_CASE(get_option_negative_zero),
	KUNIT_CASE(get_option_comma_terminated),
	KUNIT_CASE(get_option_negative_comma_terminated),
	KUNIT_CASE(get_option_range),
	KUNIT_CASE(get_option_negative_range),
	KUNIT_CASE(get_option_hyphen_without_digits),
	KUNIT_CASE(get_option_double_hyphen),
	KUNIT_CASE(get_option_no_digits),
	KUNIT_CASE(get_option_digits_then_garbage),
	KUNIT_CASE(get_option_null_pint),
	KUNIT_CASE(get_option_sequence),
	KUNIT_CASE(get_option_does_not_modify_input),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

