 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */

#include <kunit/test.h>
#include <linux/module.h>
#include <linux/string.h>

/*
 * Sentinel written to every slot of the output array before each call, so
 * that writes past the end of the caller's array (nints) are detected.
 */
#define GUARD_VAL	(-12345)
#define BUF_LEN		8

static void fill_guard(int *ints)
{
	int i;

	for (i = 0; i < BUF_LEN; i++)
		ints[i] = GUARD_VAL;
}

/* Every slot from @from onwards must still hold the sentinel. */
static void expect_guard_from(struct kunit *test, const int *ints, int from)
{
	int i;

	for (i = from; i < BUF_LEN; i++)
		KUNIT_EXPECT_EQ_MSG(test, ints[i], GUARD_VAL, "index %d", i);
}

static void expect_array(struct kunit *test, const int *got, const int *want, int n)
{
	int i;

	for (i = 0; i < n; i++)
		KUNIT_EXPECT_EQ_MSG(test, got[i], want[i], "index %d", i);
}

/* Validation mode: nints == 0, only ints[0] receives the count. */

static void get_options_validate_counts_list(struct kunit *test)
{
	const char *str = "1,2,3";
	int ints[BUF_LEN];
	char *ret;

	fill_guard(ints);
	ret = get_options(str, 0, ints);

	KUNIT_EXPECT_EQ(test, ints[0], 3);
	KUNIT_EXPECT_STREQ(test, ret, "");
	expect_guard_from(test, ints, 1);
}

static void get_options_validate_empty(struct kunit *test)
{
	int ints[BUF_LEN];
	char *ret;

	fill_guard(ints);
	ret = get_options("", 0, ints);

	KUNIT_EXPECT_EQ(test, ints[0], 0);
	KUNIT_EXPECT_STREQ(test, ret, "");
	expect_guard_from(test, ints, 1);
}

static void get_options_validate_stops_at_non_number(struct kunit *test)
{
	const char *str = "1,x";
	int ints[BUF_LEN];
	char *ret;

	fill_guard(ints);
	ret = get_options(str, 0, ints);

	KUNIT_EXPECT_EQ(test, ints[0], 1);
	KUNIT_EXPECT_STREQ(test, ret, "x");
	expect_guard_from(test, ints, 1);
}

static void get_options_validate_inclusive_range(struct kunit *test)
{
	int ints[BUF_LEN];
	char *ret;

	fill_guard(ints);
	ret = get_options("1-5", 0, ints);

	/* 1, 2, 3, 4, 5 */
	KUNIT_EXPECT_EQ(test, ints[0], 5);
	KUNIT_EXPECT_STREQ(test, ret, "");
	expect_guard_from(test, ints, 1);
}

static void get_options_validate_range_and_list(struct kunit *test)
{
	int ints[BUF_LEN];
	char *ret;

	fill_guard(ints);
	ret = get_options("1-3,7", 0, ints);

	/* 1, 2, 3, 7 */
	KUNIT_EXPECT_EQ(test, ints[0], 4);
	KUNIT_EXPECT_STREQ(test, ret, "");
	expect_guard_from(test, ints, 1);
}

static void get_options_validate_negative(struct kunit *test)
{
	int ints[BUF_LEN];
	char *ret;

	fill_guard(ints);
	ret = get_options("-5,3", 0, ints);

	KUNIT_EXPECT_EQ(test, ints[0], 2);
	KUNIT_EXPECT_STREQ(test, ret, "");
	expect_guard_from(test, ints, 1);
}

static void get_options_validate_lone_hyphen(struct kunit *test)
{
	int ints[BUF_LEN];
	char *ret;

	fill_guard(ints);
	ret = get_options("-,3", 0, ints);

	/* The hyphen is consumed but yields no integer. */
	KUNIT_EXPECT_EQ(test, ints[0], 0);
	KUNIT_EXPECT_STREQ(test, ret, ",3");
}

/* Parse mode: nints > 0, values are stored from ints[1]. */

static void get_options_null_input(struct kunit *test)
{
	int ints[BUF_LEN];
	char *ret;

	fill_guard(ints);
	ret = get_options(NULL, 4, ints);

	KUNIT_EXPECT_EQ(test, ints[0], 0);
	KUNIT_EXPECT_PTR_EQ(test, ret, NULL);
	expect_guard_from(test, ints, 4);
}

static void get_options_empty_input(struct kunit *test)
{
