	char *ret;

	fill_guard(ints);
	ret = get_options("", 4, ints);

	KUNIT_EXPECT_EQ(test, ints[0], 0);
	KUNIT_EXPECT_STREQ(test, ret, "");
	expect_guard_from(test, ints, 4);
}

static void get_options_no_room_returns_input(struct kunit *test)
{
